
import sys
import json
from pathlib import Path

import cv2

sys.path.insert(0, "backend")

from app.services.centerline import extract_centerline
from app.services.branch_diameter import calculate_branch_diameters


# Stenosis test image ID
IMAGE_ID = "74996d2933414f26a69c7dfa254ad28f"

# The geometry mask is generated by Syntax U-Net
# on the same stenosis test image.
MODEL_TYPE = "syntax"

RESULTS_DIR = Path("backend/results")
PREDICTIONS_DIR = RESULTS_DIR / "api_predictions"

# Load cleaned syntax mask for this image.
mask_path = (
    PREDICTIONS_DIR /
    f"{IMAGE_ID}_cleaned_mask.png"
)

if not mask_path.exists():
    raise FileNotFoundError(
        f"Cleaned syntax mask not found: {mask_path}\n"
        "Run syntax postprocessing for this image first."
    )

mask = cv2.imread(
    str(mask_path),
    cv2.IMREAD_GRAYSCALE
)

if mask is None:
    raise ValueError("Could not read cleaned syntax mask.")

print("\n========== INPUT INFORMATION ==========")
print("Image ID:", IMAGE_ID)
print("Input task: stenosis")
print("Geometry mask model:", MODEL_TYPE)
print("Mask path:", mask_path)
print("Mask dimensions:", mask.shape)
print("Foreground pixels:", int(cv2.countNonZero(mask)))

# Generate centerline from the cleaned vessel mask.
centerline_result = extract_centerline(mask)
centerline_mask = centerline_result["centerline_mask"]

# Calculate branch-wise diameter profiles.
result = calculate_branch_diameters(
    mask,
    centerline_mask
)

print("\n========== BRANCH DIAMETER RESULTS ==========")
print("Image ID:", IMAGE_ID)
print("Total branches:", result["branch_count"])
print("Measurement unit:", result["diameter_unit"])
print("Method:", result["measurement_method"])

print("\n========== BRANCH DIAMETER SUMMARY ==========")

for branch in result["branches"]:
    print(
        f"Branch {branch['branch_id']:2d} | "
        f"Pixels: {branch['pixel_count']:3d} | "
        f"Mean: {branch['mean_diameter_pixels']:7.3f} | "
        f"Min: {branch['minimum_diameter_pixels']:7.3f} | "
        f"Max: {branch['maximum_diameter_pixels']:7.3f}"
    )

# Create results directory if required.
RESULTS_DIR.mkdir(parents=True, exist_ok=True)

# Save an image-specific JSON report.
output_path = (
    RESULTS_DIR /
    f"{IMAGE_ID}_branch_diameter.json"
)

report = {
    "image_id": IMAGE_ID,
    "input_image_task": "stenosis",
    "geometry_mask_model": MODEL_TYPE,
    "measurement_unit": result["diameter_unit"],
    "measurement_method": result["measurement_method"],
    **result
}

with open(output_path, "w", encoding="utf-8") as file:
    json.dump(
        report,
        file,
        indent=4
    )

print("\n========== OUTPUT FILE ==========")
print("Saved diameter report:", output_path)

print("\nBranch diameter calculation completed.")
print(
    "Note: These are experimental pixel-based vessel "
    "diameters from a Syntax U-Net prediction."
)
